    "name": "갈래를 바꿔 가며 보기",
    "template": "{\n  \"weave\": \"1\",\n  \"id\": \"by-variant-1\",\n  \"title\": \"무엇에 걸렸을 때를 골라 본다\",\n  \"facets\": [\n    {\n      \"id\": \"payout\",\n      \"title\": \"진단받으면 얼마가 나오나\",\n      \"element\": \"stat\",\n      \"fields\": [\n        {\n          \"key\": \"diagnosis-benefit\",\n          \"label\": \"진단금\",\n          \"shape\": \"single\",\n          \"type\": \"money\",\n          \"description\": \"고른 갈래의 진단을 처음 받았을 때 나오는 금액을 원 단위 정수로. 여러 특약에 나눠 있으면 합산한다.\",\n          \"choice\": \"illness\"\n        }\n      ],\n      \"notes\": [\n        {\n          \"kind\": \"note\",\n          \"text\": \"갈래를 바꾸면 이 금액이 바뀝니다. 어떤 항목이 보이는지는 그대로입니다.\"\n        },\n        {\n          \"kind\": \"caution\",\n          \"text\": \"진단금은 진단 확정일 기준이고 지급 조건은 약관이 정합니다.\"\n        }\n      ]\n    },\n    {\n      \"id\": \"coverage\",\n      \"title\": \"무엇이 얼마나 붙어 있나\",\n      \"element\": \"bars\",\n      \"fields\": [\n        {\n          \"key\": \"diagnosis\",\n          \"label\": \"진단\",\n          \"shape\": \"single\",\n          \"type\": \"money\",\n          \"description\": \"고른 갈래의 진단 특약 가입금액을 원 단위 정수로.\",\n          \"choice\": \"illness\"\n        },\n        {\n          \"key\": \"hospital\",\n          \"label\": \"입원\",\n          \"shape\": \"single\",\n          \"type\": \"money\",\n          \"description\": \"고른 갈래로 입원했을 때 하루당 나오는 금액을 원 단위 정수로.\",\n          \"choice\": \"illness\"\n        },\n        {\n          \"key\": \"premium\",\n          \"label\": \"월 보험료\",\n          \"shape\": \"single\",\n          \"type\": \"money\",\n          \"description\": \"이 설계 전체의 월 보험료를 원 단위 정수로. 갈래와 무관하게 하나다.\"\n        }\n      ],\n      \"notes\": [\n        {\n          \"kind\": \"tip\",\n          \"text\": \"월 보험료는 갈래를 바꿔도 그대로입니다 — 설계 하나에 하나뿐이라 갈리지 않습니다.\"\n        }\n      ]\n    }\n  ],\n  \"choices\": [\n    {\n      \"id\": \"illness\",\n      \"label\": \"무엇에 걸렸을 때\",\n      \"options\": [\n        {\n          \"id\": \"cancer\",\n          \"label\": \"암\"\n        },\n        {\n          \"id\": \"brain\",\n          \"label\": \"뇌혈관\"\n        },\n        {\n          \"id\": \"heart\",\n          \"label\": \"허혈성심장\"\n        }\n      ]\n    }\n  ]\n}\n",
